package com.edgeos.launcher; import android.app.*;import android.os.*;import android.graphics.*;import android.content.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class SettingsActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(22,30,22,22);r.setBackgroundColor(0xFF111318);TextView h=Ui.text(this,"EDGE OS Settings",28,Color.WHITE);h.setGravity(Gravity.LEFT);r.addView(h,new LinearLayout.LayoutParams(-1,70));add(r,"Dark appearance",v->{LauncherPrefs.setDark(this,!LauncherPrefs.dark(this));});add(r,"Accessibility / AssistiveTouch",v->{try{startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(Exception e){}});add(r,"Display overlay permission",v->{try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,android.net.Uri.parse("package:"+getPackageName())));}catch(Exception e){}});add(r,"Notification access",v->{try{startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"));}catch(Exception e){}});add(r,"Lock Screen preview",v->startActivity(new Intent(this,LockScreenActivity.class)));TextView info=Ui.text(this,"M1–M14 • Android 8.1+ • no Internet permission • event-driven",12,0xFFAAAAAA);r.addView(info,new LinearLayout.LayoutParams(-1,70));setContentView(r);}void add(LinearLayout r,String s,View.OnClickListener l){Button b=Ui.pill(this,s);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setOnClickListener(l);r.addView(b,new LinearLayout.LayoutParams(-1,58));}}
